@page "/settings"
@rendermode InteractiveServer
@using sv_0cb0f4f83d2142239bf9a0f7093c9920.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (ActiveSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (_profile is not null)
                {
                    <div class="profile-layout">
                        <div class="avatar-area">
                            <img src="@_editProfile!.AvatarUrl" alt="Avatar" class="avatar-preview" />
                            <p class="avatar-url">@_editProfile.AvatarUrl</p>
                        </div>
                        <div class="form-fields">
                            <div class="form-group">
                                <label for="displayName">Display Name</label>
                                <input id="displayName" type="text" @bind="_editProfile.DisplayName" />
                            </div>
                            <div class="form-group">
                                <label for="email">Email</label>
                                <input id="email" type="email" @bind="_editProfile.Email" />
                            </div>
                            <div class="form-group">
                                <label for="bio">Bio</label>
                                <textarea id="bio" rows="4" @bind="_editProfile.Bio"></textarea>
                            </div>
                            <div class="button-group">
                                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (_editNotifications is not null)
                {
                    <div class="form-fields">
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotifications.EmailNotifications" />
                                <span class="toggle-switch"></span>
                                Email Notifications
                            </label>
                        </div>
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotifications.PushNotifications" />
                                <span class="toggle-switch"></span>
                                Push Notifications
                            </label>
                        </div>
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotifications.WeeklyDigest" />
                                <span class="toggle-switch"></span>
                                Weekly Digest
                            </label>
                        </div>

                        <h3>Muted Channels</h3>
                        <div class="channel-list">
                            @foreach (var channel in _allChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@_editNotifications.MutedChannels.Contains(channel)"
                                           @onchange="(e) => ToggleMutedChannel(channel, (bool)e.Value!)" />
                                    @channel
                                </label>
                            }
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (_security is not null)
                {
                    <div class="form-fields">
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="TogglePasswordPanel">
                                <span>Change Password</span>
                                <span class="expand-icon">@(_showPasswordPanel ? "▾" : "▸")</span>
                            </button>
                            @if (_showPasswordPanel)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="_newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                                    </div>
                                    <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" checked="@_security.TwoFactorEnabled" disabled />
                                <span class="toggle-switch"></span>
                                Two-Factor Authentication
                                <span class="status-indicator @(_security.TwoFactorEnabled ? "enabled" : "disabled")">
                                    @(_security.TwoFactorEnabled ? "Enabled" : "Disabled")
                                </span>
                            </label>
                        </div>

                        @if (_security.LastPasswordChange.HasValue)
                        {
                            <p class="info-text">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <div class="sessions-table-wrapper">
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @foreach (var session in _security.Sessions)
                                    {
                                        <tr>
                                            <td>@session.Device</td>
                                            <td>@session.Location</td>
                                            <td>@FormatLastActive(session.LastActive)</td>
                                            <td>
                                                @if (session.Id == _security.Sessions.First().Id)
                                                {
                                                    <span class="current-session">Current</span>
                                                }
                                                else
                                                {
                                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                                }
                                            </td>
                                        </tr>
                                    }
                                </tbody>
                            </table>
                        </div>
                    </div>

                    @if (_showRevokeConfirm && _sessionToRevoke is not null)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (_editAppearance is not null)
                {
                    <div class="form-fields">
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label><input type="radio" name="theme" value="Light" checked="@(_editAppearance.Theme == "Light")" @onchange='() => _editAppearance.Theme = "Light"' /> Light</label>
                                <label><input type="radio" name="theme" value="Dark" checked="@(_editAppearance.Theme == "Dark")" @onchange='() => _editAppearance.Theme = "Dark"' /> Dark</label>
                                <label><input type="radio" name="theme" value="System" checked="@(_editAppearance.Theme == "System")" @onchange='() => _editAppearance.Theme = "System"' /> System</label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label><input type="radio" name="fontSize" value="Small" checked="@(_editAppearance.FontSize == "Small")" @onchange='() => _editAppearance.FontSize = "Small"' /> Small</label>
                                <label><input type="radio" name="fontSize" value="Medium" checked="@(_editAppearance.FontSize == "Medium")" @onchange='() => _editAppearance.FontSize = "Medium"' /> Medium</label>
                                <label><input type="radio" name="fontSize" value="Large" checked="@(_editAppearance.FontSize == "Large")" @onchange='() => _editAppearance.FontSize = "Large"' /> Large</label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label for="language">Language</label>
                            <select id="language" @bind="_editAppearance.Language">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editAppearance.CompactMode" />
                                <span class="toggle-switch"></span>
                                Compact Mode
                            </label>
                        </div>

                        <h3>Preview</h3>
                        <div class="appearance-preview @GetPreviewClasses()">
                            <div class="preview-header">Sample Header</div>
                            <p class="preview-text">This is a preview of how your content will look with the selected appearance settings.</p>
                            <div class="preview-card">
                                <strong>Card Title</strong>
                                <p>Card content with the chosen theme and font size.</p>
                            </div>
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </div>
                }
            </section>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile
    private UserProfile? _profile;
    private ProfileEdit? _editProfile;

    // Notifications
    private NotificationPrefs? _notifications;
    private NotificationEdit? _editNotifications;
    private readonly List<string> _allChannels = new() { "general", "marketing", "engineering", "design", "announcements" };

    // Security
    private SecuritySettings? _security;
    private bool _showPasswordPanel;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceSettings? _appearance;
    private AppearanceEdit? _editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadSection();
    }

    private async Task SetSection(string section)
    {
        ActiveSection = section;
        await LoadSection();
    }

    private async Task LoadSection()
    {
        switch (ActiveSection)
        {
            case "Profile":
                _profile = await SettingsService.GetProfileAsync();
                _editProfile = new ProfileEdit(_profile);
                break;
            case "Notifications":
                _notifications = await SettingsService.GetNotificationPrefsAsync();
                _editNotifications = new NotificationEdit(_notifications);
                break;
            case "Security":
                _security = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                _appearance = await SettingsService.GetAppearanceAsync();
                _editAppearance = new AppearanceEdit(_appearance);
                break;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        if (_editProfile is null) return;
        var updated = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
            _editProfile = new ProfileEdit(_profile);
    }

    // Notification methods
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (_editNotifications is null) return;
        if (isMuted && !_editNotifications.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            _editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        if (_editNotifications is null) return;
        var updated = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notifications = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => _showPasswordPanel = !_showPasswordPanel;

    private async Task ChangePassword()
    {
