@code {
    private string ActiveSection { get; set; } = "Profile";
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile
    private UserProfile? _profile;
    private ProfileEdit? _editProfile;

    // Notifications
    private NotificationPrefs? _notifications;
    private NotificationEdit? _editNotifications;
    private readonly List<string> _allChannels = new() { "general", "marketing", "engineering", "design", "announcements" };

    // Security
    private SecuritySettings? _security;
    private bool _showPasswordPanel;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceSettings? _appearance;
    private AppearanceEdit? _editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadSection();
    }

    private async Task SetSection(string section)
    {
        ActiveSection = section;
        await LoadSection();
    }

    private async Task LoadSection()
    {
        switch (ActiveSection)
        {
            case "Profile":
                _profile = await SettingsService.GetProfileAsync();
                _editProfile = new ProfileEdit(_profile);
                break;
            case "Notifications":
                _notifications = await SettingsService.GetNotificationPrefsAsync();
                _editNotifications = new NotificationEdit(_notifications);
                break;
            case "Security":
                _security = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                _appearance = await SettingsService.GetAppearanceAsync();
                _editAppearance = new AppearanceEdit(_appearance);
                break;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        if (_editProfile is null) return;
        var updated = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
            _editProfile = new ProfileEdit(_profile);
    }

    // Notification methods
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (_editNotifications is null) return;
        if (isMuted && !_editNotifications.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            _editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        if (_editNotifications is null) return;
        var updated = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notifications = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => _showPasswordPanel = !_showPasswordPanel;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _showPasswordPanel = false;
        _security = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
        ShowToast("Session revoked.", "success");
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        if (_editAppearance is null) return "";
        var classes = $"preview-theme-{_editAppearance.Theme.ToLower()} preview-font-{_editAppearance.FontSize.ToLower()}";
        if (_editAppearance.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        if (_editAppearance is null) return;
        var updated = new AppearanceSettings(_editAppearance.Theme, _editAppearance.FontSize, _editAppearance.Language, _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        ToastMessage = message;
        ToastType = type;
        _ = Task.Delay(3000).ContinueWith(_ =>
        {
            ToastMessage = null;
            InvokeAsync(StateHasChanged);
        });
    }

    private void DismissToast() => ToastMessage = null;

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Editable model classes
    private class ProfileEdit
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileEdit(UserProfile p)
        {
            DisplayName = p.DisplayName;
            Email = p.Email;
            AvatarUrl = p.AvatarUrl;
            Bio = p.Bio;
        }
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public NotificationEdit(NotificationPrefs p)
        {
            EmailNotifications = p.EmailNotifications;
            PushNotifications = p.PushNotifications;
            WeeklyDigest = p.WeeklyDigest;
            MutedChannels = new List<string>(p.MutedChannels);
        }
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; }
        public string FontSize { get; set; }
        public string Language { get; set; }
        public bool CompactMode { get; set; }

        public AppearanceEdit(AppearanceSettings a)
        {
            Theme = a.Theme;
            FontSize = a.FontSize;
            Language = a.Language;
            CompactMode = a.CompactMode;
        }
    }
}
