+    background: #1e293b;
+    color: #e2e8f0;
+}
+
+.appearance-preview.preview-theme-system {
+    background: #f8fafc;
+    color: #334155;
+}
+
+.appearance-preview.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.appearance-preview.preview-font-medium {
+    font-size: 1rem;
+}
+
+.appearance-preview.preview-font-large {
+    font-size: 1.2rem;
+}
+
+.appearance-preview.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-header {
+    font-weight: 700;
+    font-size: 1.2em;
+    margin-bottom: 0.5rem;
+}
+
+.preview-card {
+    border: 1px solid currentColor;
+    border-radius: 6px;
+    padding: 0.75rem;
+    margin-top: 0.75rem;
+    opacity: 0.8;
+}
+
+.preview-card p {
+    margin: 0.25rem 0 0;
+}
+
+/* Toast */
+.toast {
+    position: absolute;
+    top: 1rem;
+    right: 1rem;
+    padding: 0.75rem 1.25rem;
+    border-radius: 8px;
+    font-size: 0.9rem;
+    font-weight: 500;
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    animation: slideIn 0.3s ease;
+    z-index: 100;
+}
+
+.toast.success {
+    background: #dcfce7;
+    color: #166534;
+    border: 1px solid #bbf7d0;
+}
+
+.toast.error {
+    background: #fef2f2;
+    color: #991b1b;
+    border: 1px solid #fecaca;
+}
+
+.toast-close {
+    background: none;
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    opacity: 0.6;
+    color: inherit;
+}
+
+.toast-close:hover {
+    opacity: 1;
+}
+
+@keyframes slideIn {
+    from {
+        transform: translateX(1rem);
+        opacity: 0;
+    }
+    to {
+        transform: translateX(0);
+        opacity: 1;
+    }
+}
+
